"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[4823],{58476(a,n,e){e.r(n),e.d(n,{assets:()=>r,contentTitle:()=>m,default:()=>d,frontMatter:()=>k,metadata:()=>i,toc:()=>l});const i=JSON.parse('{"id":"learning/courses/quantum-computing-in-practice/introduction","title":"Pengenalan","description":"Kursus IBM percuma tentang pengkomputeran kuantum berskala utiliti yang menampilkan kes penggunaan realistik dan amalan terbaik","source":"@site/i18n/ms/docusaurus-plugin-content-docs/current/learning/courses/quantum-computing-in-practice/introduction.mdx","sourceDirName":"learning/courses/quantum-computing-in-practice","slug":"/learning/courses/quantum-computing-in-practice/introduction","permalink":"/learning/courses/quantum-computing-in-practice/introduction","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/quantum-computing-in-practice/introduction.mdx","tags":[],"version":"current","frontMatter":{"title":"Pengenalan","sidebar_label":"Pengenalan","description":"Kursus IBM percuma tentang pengkomputeran kuantum berskala utiliti yang menampilkan kes penggunaan realistik dan amalan terbaik","notebook_path":"learning/courses/quantum-computing-in-practice/introduction.ipynb"},"sidebar":"tutorialsSidebar","previous":{"title":"Gambaran Keseluruhan","permalink":"/learning/courses/quantum-computing-in-practice/"},"next":{"title":"Menjalankan Circuit kuantum","permalink":"/learning/courses/quantum-computing-in-practice/running-quantum-circuits"}}');var t=e(74848),u=e(28453);const k={title:"Pengenalan",sidebar_label:"Pengenalan",description:"Kursus IBM percuma tentang pengkomputeran kuantum berskala utiliti yang menampilkan kes penggunaan realistik dan amalan terbaik",notebook_path:"learning/courses/quantum-computing-in-practice/introduction.ipynb"},m="Pengenalan kursus {#course-introduction}",r={},l=[{value:"Tentang kursus ini",id:"about-this-course",level:2},{value:"Utiliti kuantum",id:"quantum-utility",level:3},{value:"Mensimulasi Alam Semesta",id:"simulating-nature",level:3},{value:"Fokus pada pemproses kuantum yang lebih besar",id:"a-focus-on-larger-quantum-processors",level:3},{value:"Penonton dan matlamat kursus",id:"audience-and-course-goals",level:3},{value:"Kisah pengkomputeran",id:"the-story-of-computation",level:2},{value:"Peranti pengkomputeran sejak zaman purba",id:"computing-devices-since-ancient-times",level:3},{value:"Hubungan dengan dunia fizikal",id:"connections-to-the-physical-world",level:3},{value:"Hukum Moore",id:"moores-law",level:3},{value:"Pengkomputeran kuantum",id:"quantum-computing",level:2},{value:"Mekanik kuantum dan pengkomputeran",id:"quantum-mechanics-and-computation",level:3},{value:"Pengkomputeran kuantum dalam teori",id:"quantum-computing-in-theory",level:3},{value:"Pengkomputeran kuantum dalam praktik",id:"quantum-computing-in-practice",level:3},{value:"Aplikasi berpotensi",id:"potential-applications",level:3},{value:"Keadaan teknologi",id:"state-of-the-technology",level:3},{value:"Kesimpulan",id:"conclusion",level:2}];function s(a){const n={a:"a",blockquote:"blockquote",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,u.R)(),...a.components},{IBMVideo:e}=n;return e||function(a,n){throw new Error("Expected "+(n?"component":"object")+" `"+a+"` to be defined: you likely forgot to import, pass, or provide it.")}("IBMVideo",!0),(0,t.jsxs)(t.Fragment,{children:["\n",(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"course-introduction",children:"Pengenalan kursus"})}),"\n",(0,t.jsxs)(n.p,{children:["Sebelum bermula, sila lengkapkan ",(0,t.jsx)(n.a,{href:"https://your.feedback.ibm.com/jfe/form/SV_6PadhMQiGWsxXTM",children:"tinjauan pra-kursus"})," yang ringkas ini, yang penting untuk membantu menambah baik tawaran kandungan dan pengalaman pengguna kami."]}),"\n",(0,t.jsxs)(n.blockquote,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Note:"})," This survey is provided by IBM Quantum and relates to the original English content. To give feedback on doQumentation's website, translations, or code execution, please ",(0,t.jsx)(n.a,{href:"https://github.com/JanLahmann/doQumentation/issues",children:"open a GitHub issue"}),"."]}),"\n"]}),"\n",(0,t.jsxs)(n.p,{children:["Klik di bawah untuk mendengar pengenalan kursus daripada Olivia Lanes, atau buka video dalam tetingkap berasingan di ",(0,t.jsx)(n.a,{href:"https://youtube.com/watch?v=sVRpKhCfKRI",children:"YouTube."})]}),"\n",(0,t.jsx)(e,{id:"134063425",title:"In this video, Olivia Lanes gives an overview of practical quantum computing in the utility era. She covers intended audience and some background on subjects like Moore's law and theoretical foundations of quantum computing."}),"\n",(0,t.jsx)(n.h2,{id:"about-this-course",children:"Tentang kursus ini"}),"\n",(0,t.jsxs)(n.p,{children:["Selamat datang ke ",(0,t.jsx)(n.em,{children:"Pengkomputeran Kuantum dalam Praktik"})," \u2014 kursus yang memberi tumpuan kepada komputer kuantum hari ini dan cara menggunakannya sepenuhnya.\nIa merangkumi kes penggunaan berpotensi yang realistik untuk pengkomputeran kuantum serta amalan terbaik untuk menjalankan dan bereksperimen dengan pemproses kuantum yang mempunyai 100 qubit atau lebih."]}),"\n",(0,t.jsx)(n.h3,{id:"quantum-utility",children:"Utiliti kuantum"}),"\n",(0,t.jsxs)(n.p,{children:["Ini adalah masa yang menarik untuk pengkomputeran kuantum.\nSelepas bertahun-tahun penyelidikan dan pembangunan teori serta eksperimen, komputer kuantum semakin mendekati titik di mana mereka boleh mula bersaing dengan komputer klasik dan menunjukkan ",(0,t.jsx)(n.em,{children:"utiliti"}),"."]}),"\n",(0,t.jsxs)(n.p,{children:["Utiliti bukan perkara yang sama dengan ",(0,t.jsx)(n.em,{children:"kelebihan kuantum"}),", yang merujuk kepada komputer kuantum yang ",(0,t.jsx)(n.em,{children:"mengatasi"})," komputer klasik untuk tugasan bermakna.\nKomputer klasik mempunyai kuasa dan kebolehsuaian yang luar biasa, dan hakikatnya ialah komputer kuantum masih belum mampu mengalahkan mereka.\nKita telah menyaksikan dekad kemajuan dalam pengkomputeran klasik \u2014 bukan sahaja dalam perkakasan pengkomputeran tetapi juga dalam algoritma untuk komputer klasik \u2014 dan kita dapat melihat dengan jelas bahawa teknologi pengkomputeran digital elektronik telah mengubah dunia kita secara drastik."]}),"\n",(0,t.jsxs)(n.p,{children:["Pengkomputeran kuantum, sebaliknya, berada pada peringkat perkembangan yang berbeza.\nPengkomputeran kuantum menuntut kawalan yang ekstrem ke atas sistem mekanikal kuantum dan menolak batas teknologi hari ini \u2014 dan kita tidak boleh mengharapkan secara realistik untuk menguasai teknologi baru ini dan mengalahkan pengkomputeran klasik sejurus sahaja bermula.\nTetapi kita melihat tanda-tanda yang mencadangkan bahawa komputer kuantum mula menjadi kompetitif dengan kaedah pengkomputeran klasik untuk tugasan terpilih, yang merupakan langkah semula jadi dalam evolusi teknologi pengkomputeran kuantum yang dikenali sebagai ",(0,t.jsx)(n.em,{children:"utiliti kuantum"}),"."]}),"\n",(0,t.jsx)(n.p,{children:"Apabila teknologi berkembang dan kaedah baharu untuk pengkomputeran kuantum dibangunkan, kita boleh menjangkakan secara munasabah bahawa kelebihannya akan semakin ketara \u2014 tetapi ini memerlukan masa.\nSemasa ini berlaku, kita mungkin akan melihat interaksi berulang dengan pengkomputeran klasik:\ndemonstrasi pengkomputeran kuantum akan dilakukan dan pengkomputeran klasik akan memberi respons, pengkomputeran kuantum akan mengambil giliran lain, dan corak akan berulang.\nDan suatu hari, apabila prestasi komputer kuantum tidak dapat dipadankan secara klasik, kita akan berhipotesis bahawa kita telah menyaksikan kelebihan kuantum \u2014 tetapi walaupun ketika itu kita tidak akan pasti!\nMembuktikan hasil kemustahilan untuk komputer klasik adalah masalah yang mustahil sukar setakat yang kita tahu."}),"\n",(0,t.jsx)(n.h3,{id:"simulating-nature",children:"Mensimulasi Alam Semesta"}),"\n",(0,t.jsx)(n.p,{children:"Simulator klasik \u2014 bermaksud program komputer yang berjalan pada komputer klasik yang mensimulasi sistem fizikal \u2014 boleh membuat ramalan tentang sistem mekanikal kuantum.\nTetapi simulator klasik bukan kuantum dan tidak boleh meniru sistem kuantum secara langsung.\nSebaliknya mereka menggunakan pengiraan matematik untuk menghampiri tingkah laku kuantum.\nApabila saiz sistem yang disimulasi berkembang, overhed yang diperlukan untuk melakukan ini meningkat secara dramatik, meletakkan had pada sistem kuantum mana yang boleh disimulasi secara klasik, berapa lama simulasi memerlukan, dan ketepatan keputusan."}),"\n",(0,t.jsx)(n.p,{children:"Komputer kuantum, sebaliknya, boleh meniru sistem kuantum secara lebih langsung \u2014 dan hasilnya, overhed yang diperlukan berskala jauh lebih baik apabila saiz sistem berkembang.\nIni, sebenarnya, adalah idea Richard Feynman pada tahun 1980-an yang pertama kali mendorong penyiasatan ke atas potensi komputer kuantum.\nKita akan bercakap lebih lanjut tentang ini kemudian!"}),"\n",(0,t.jsx)(n.p,{children:"Penyelidik IBM\xae menerbitkan makalah pada tahun 2023 yang menunjukkan, buat pertama kalinya, bahawa komputer kuantum boleh bersaing dengan teknik klasik terkini untuk mensimulasi model fizikal tertentu.\nHasilnya masih boleh dipadankan oleh teknik lanjutan yang berjalan pada komputer klasik \u2014 tetapi ia mengatasi algoritma brute-force,\ndan ia juga menawarkan titik data baharu untuk perbandingan kaedah simulasi yang berbeza (yang tidak tepat dan tidak semua bersetuju dalam ramalan mereka)."}),"\n",(0,t.jsx)(n.h3,{id:"a-focus-on-larger-quantum-processors",children:"Fokus pada pemproses kuantum yang lebih besar"}),"\n",(0,t.jsx)(n.p,{children:"Pengguna lama perkakasan kuantum IBM mungkin telah perasan bahawa pemproses yang lebih kecil yang sebelumnya kami sediakan kepada orang awam telah diambil tidak dalam talian, memberi laluan kepada pemproses yang lebih besar (mempunyai 100+ qubit).\nPemproses yang lebih kecil itu boleh dengan mudah disimulasi secara klasik.\nJadi, walaupun mereka mewakili batu loncatan yang boleh diakses awam dalam teknologi yang semakin maju, mereka tidak mungkin menunjukkan utiliti kuantum: apa sahaja yang boleh dilakukan dengan mereka boleh dilakukan sama mudah dengan simulasi klasik."}),"\n",(0,t.jsxs)(n.p,{children:["Pada sekitar 100 qubit, bagaimanapun, ini bukan lagi keadaannya; pemproses kuantum bersaiz ini tidak lagi boleh disimulasi secara klasik.\nIni mewakili semacam peralihan fasa, ke era baharu teknologi pengkomputeran kuantum di mana ",(0,t.jsx)(n.em,{children:"potensi"})," untuk mengatasi pengkomputeran klasik wujud.\nDi sinilah IBM telah memilih untuk memberi tumpuan \u2014 mencari kuasa pengkomputeran kuantum dan menghampiri kelebihan kuantum akhirnya."]}),"\n",(0,t.jsx)(n.p,{children:"Kami menggalakkan pengguna kami untuk menggunakan peranti baharu ini sepenuhnya, bereksperimen dengan mereka dan menolak had mereka, dan membawa pelajaran yang dipelajari ke generasi seterusnya pemproses kuantum yang sedang dalam pembangunan.\nTujuan kursus ini adalah untuk membolehkan anda melakukan ini!"}),"\n",(0,t.jsx)(n.h3,{id:"audience-and-course-goals",children:"Penonton dan matlamat kursus"}),"\n",(0,t.jsx)(n.p,{children:"Kursus ini untuk sesiapa yang bertujuan untuk membangunkan aplikasi baharu untuk komputer kuantum, ingin meningkatkan kerja semasa mereka dalam pengkomputeran kuantum, atau belajar cara menggunakan pemproses kuantum dalam aliran kerja mereka.\nIni termasuk bukan sahaja ahli fizik dan saintis komputer, tetapi juga jurutera, ahli kimia, saintis bahan, dan sesiapa sahaja yang berminat untuk menguasai perkakasan pengkomputeran kuantum."}),"\n",(0,t.jsx)(n.p,{children:"Kursus ini akan bersifat praktikal dan memberi tumpuan kepada penggunaan komputer kuantum yang praktikal.\nTopik dan kemahiran berikut adalah antara yang diliputi:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"Menjalankan kerja berskala utiliti pada pemproses kuantum melalui Qiskit Runtime"}),"\n",(0,t.jsx)(n.li,{children:"Menggunakan teknik mitigasi ralat untuk meningkatkan keputusan perkakasan"}),"\n",(0,t.jsx)(n.li,{children:"Kawasan aplikasi berpotensi untuk komputer kuantum jangka pendek"}),"\n"]}),"\n",(0,t.jsxs)(n.p,{children:["Kursus ini tidak merangkumi teori pengenalan pengkomputeran kuantum, dan mengandaikan kebiasaan asas dengan qubit dan Circuit kuantum.\nKursus ",(0,t.jsx)(n.em,{children:"Asas maklumat kuantum"})," pada platform ini meliputi bahan ini, dan disyorkan terlebih dahulu bagi mereka yang baharu dalam pengkomputeran kuantum."]}),"\n",(0,t.jsx)(n.h2,{id:"the-story-of-computation",children:"Kisah pengkomputeran"}),"\n",(0,t.jsxs)(n.p,{children:["Pengkomputeran kuantum adalah teknologi baharu yang menarik dalam peringkat awal pembangunan \u2014 tetapi ia hanyalah satu bab dalam kisah yang bermula beribu-ribu tahun lalu.\nIa adalah kisah tentang ",(0,t.jsx)(n.em,{children:"pengkomputeran"})," dan hubungannya yang pelbagai rupa dengan ",(0,t.jsx)(n.em,{children:"dunia fizikal"}),"."]}),"\n",(0,t.jsx)(n.h3,{id:"computing-devices-since-ancient-times",children:"Peranti pengkomputeran sejak zaman purba"}),"\n",(0,t.jsxs)(n.p,{children:["Sejak zaman purba, kita sebagai manusia perlu melakukan ",(0,t.jsx)(n.em,{children:"pengiraan"})," \u2014 atau, dengan kata lain, memproses maklumat mengikut peraturan dan kekangan tertentu \u2014 untuk membolehkan komunikasi, pembinaan, perdagangan, sains, dan aspek kehidupan kita yang lain.\nKita telah melihat kepada dunia fizikal untuk bantuan, dan melalui penemuan yang bijak kita telah membina peranti untuk membantu kita mengira."]}),"\n",(0,t.jsxs)(n.p,{children:["Dahulu kala, peranti yang diperbuat daripada kayu, tulang, dan tali bersimpul menyimpan maklumat dan memudahkan pengiraan.\nPeranti mekanikal yang dibina daripada tuas, gear, dan jentera lain berkembang daripada jam astronomi awal, kepada kalkulator, kepada peranti pengkomputeran canggih seperti penganalisis pembeza yang menyelesaikan persamaan menggunakan roda dan cakera berputar.\nMalah teknologi penulisan telah memainkan peranan penting dalam kisah ini dengan membolehkan ",(0,t.jsx)(n.em,{children:"orang"})," melakukan pengiraan yang tidak boleh mereka lakukan selainnya."]}),"\n",(0,t.jsx)(n.p,{children:"Apabila kita memikirkan tentang komputer hari ini, kita cenderung memikirkan tentang komputer digital elektronik.\nTetapi ini sebenarnya adalah teknologi yang agak baru: komputer digital elektronik pertama kali dibina pada tahun 1940-an.\n(Berbanding dengan itu, abakus Sumeria dipercayai telah dicipta di suatu tempat antara 2700 dan 2300 SM.)\nTeknologi ini telah maju secara dramatik sejak itu dan komputer kini menjadi lazim.\nMereka ditemui di rumah, tempat kerja, dan kenderaan yang mengangkut kita di antara mereka, dan ramai daripada kita membawanya ke mana-mana kita pergi."}),"\n",(0,t.jsxs)(n.p,{children:["Kita juga mempunyai ",(0,t.jsx)(n.em,{children:"superkomputer"}),", yang merupakan koleksi besar pemproses klasik yang berkuasa dihubungkan secara selari.\nMereka antara alat terbaik yang pernah dibina manusia untuk menyelesaikan masalah yang sukar, dan kuasa serta kebolehpercayaannya terus maju.\nTetapi masih ada masalah pengkomputeran penting yang walaupun raksasa ini tidak akan pernah dapat menyelesaikannya, disebabkan kesukaran pengkomputeran yang wujud dalam masalah-masalah ini."]}),"\n",(0,t.jsx)(n.h3,{id:"connections-to-the-physical-world",children:"Hubungan dengan dunia fizikal"}),"\n",(0,t.jsxs)(n.p,{children:["Komputer mempunyai banyak kegunaan.\nSatu kegunaan penting untuk komputer adalah untuk ",(0,t.jsx)(n.em,{children:"mempelajari"})," tentang dunia fizikal dan lebih memahami coraknya.\nPenggunaan bersejarah dalam kategori ini telah merangkumi ramalan gerhana dan pasang surut, memahami pergerakan badan astronomi, dan (dalam masa yang agak lebih baru) pemodelan letupan.\nHari ini hampir tiada makmal fizik di dunia tanpa komputer."]}),"\n",(0,t.jsxs)(n.p,{children:["Secara lebih umum, fizik dan pengkomputeran sentiasa saling berkaitan.\nPengkomputeran tidak boleh wujud dalam vakum: maklumat memerlukan medium, dan untuk mengira kita perlu memanfaatkan dunia fizikal dalam beberapa hal.\nRolf Launduer, seorang saintis komputer (dan orang IBM), mengiktiraf beberapa dekad lalu bahawa maklumat adalah fizikal, wujud hanya melalui perwakilan fizikal.\n",(0,t.jsx)(n.em,{children:"Prinsip Landauer"})," mewujudkan hubungan antara maklumat dan undang-undang termodinamik, tetapi sebenarnya terdapat banyak hubungan."]}),"\n",(0,t.jsx)(n.p,{children:"Memahami dunia fizikal adalah matlamat fizik sebagai disiplin, tetapi sebenarnya ia adalah jalan dua hala.\nMelalui pemahaman kita tentang dunia fizikal, kita dapat memanfaatkan teknologi baharu untuk membantu kita mengira, dan melalui mereka kita terus belajar tentang dunia fizikal \u2014 pada dasarnya menarik fizik dan teknologi pengkomputeran ke atas dengan tali kasut sendiri."}),"\n",(0,t.jsx)(n.h3,{id:"moores-law",children:"Hukum Moore"}),"\n",(0,t.jsx)(n.p,{children:"Hukum Moore adalah pemerhatian bahawa bilangan maksimum transistor dalam litar bersepadu berganda kira-kira setiap 2 tahun.\nSelama kira-kira 5 dekad yang lalu, kita bukan sahaja memerhati trend ini tetapi juga menuai hasilnya.\nDengan lebih banyak transistor pada cip, kita boleh melakukan pengiraan yang lebih kompleks dan kita boleh melakukannya lebih cepat.\nInilah sebabnya komputer semakin berkuasa dari masa ke masa."}),"\n",(0,t.jsx)(n.p,{children:'Walau bagaimanapun, "hukum" Moore, dengan keperluan, akan berakhir.\nPakar tidak bersetuju pada bila ini akan berlaku, dan ada yang berpendapat ia sudah berlaku.\nTetapi kita tahu dengan pasti bahawa ia mesti berakhir pada akhirnya kerana terdapat had teori untuk pengecilan komponen pengkomputeran.\nKita tidak boleh membuat transistor lebih kecil daripada atom!\nWalaupun itu mungkin kedengaran keterlaluan, inilah dinding yang kita hampiri.'}),"\n",(0,t.jsx)(n.p,{children:'Penyelesaiannya bukan untuk menyerah dan berkata, "Baiklah, itulah sebaik yang boleh dicapai."\nIni bertentangan dengan sifat manusia.\nSebaliknya kita mesti mencari alat pengkomputeran baharu dalam dunia fizikal, dan di situlah pengkomputeran kuantum berperanan.'}),"\n",(0,t.jsx)(n.h2,{id:"quantum-computing",children:"Pengkomputeran kuantum"}),"\n",(0,t.jsx)(n.h3,{id:"quantum-mechanics-and-computation",children:"Mekanik kuantum dan pengkomputeran"}),"\n",(0,t.jsx)(n.p,{children:"Mekanik kuantum ditemui pada awal abad ke-20, dan ia telah memainkan peranan penting dalam pengkomputeran.\nMemang, pemahaman kita tentang mekanik kuantum telah, sebahagiannya, menjadikan komputer moden mungkin.\nTanpa mekanik kuantum, misalnya, sukar untuk membayangkan pemacu keras keadaan pepejal telah dicipta."}),"\n",(0,t.jsx)(n.h3,{id:"quantum-computing-in-theory",children:"Pengkomputeran kuantum dalam teori"}),"\n",(0,t.jsx)(n.p,{children:"Apabila Richard Feynman pertama kali mencadangkan konsep komputer kuantum pada tahun 1982, fokusnya adalah pada pensimulasian sistem mekanikal kuantum.\nPengiraan yang diperlukan untuk melakukan ini kelihatan terlalu sukar untuk komputer biasa \u2014 tetapi mungkin, dengan komputer yang beroperasi mengikut penerangan mekanikal kuantum tentang dunia, sistem boleh ditiru secara langsung."}),"\n",(0,t.jsx)(n.p,{children:"Hari ini ini adalah salah satu jalan yang paling menjanjikan untuk pengkomputeran kuantum.\nSejauh pemahaman terbaik kita, Alam Semesta bukan klasik \u2014 ia adalah kuantum.\nOleh itu, komputer kuantum mungkin menjadi alat berharga untuk memahaminya.\nKomputer klasik, sebaliknya, hanya boleh menghampiri apa yang sebenarnya berlaku dalam Alam Semesta, dan dalam sesetengah kes penghampiran tersebut\nsangat terhad."}),"\n",(0,t.jsx)(n.p,{children:"Satu cara untuk memikirkan tentang ini adalah melalui analogi kepada terowong angin.\nDinamik bendalir terkenal sukar untuk disimulasi dan diramalkan secara matematik.\nSebagai contoh, terlalu mahal dan tidak praktikal untuk mensimulasi kereta yang memandu melalui angin, jadi sebaliknya pengeluar kereta sebenarnya membina terowong dengan angin yang bertiup dan memandu kereta melaluinya untuk menguji prestasi mereka.\nIaitu, mereka mencipta angin daripada mensimulasikannya.\nMembina komputer kuantum untuk mengkaji dunia fizikal adalah seperti membina terowong angin untuk mengkaji bagaimana angin mempengaruhi kereta.\nKomputer kuantum boleh meniru secara langsung undang-undang Alam Semesta pada peringkat molekul kerana mereka bertindak mengikut undang-undang tersebut,\nyang bermaksud mereka meniru Alam Semesta dan bukannya mensimulasikannya melalui formula dan pengiraan."}),"\n",(0,t.jsxs)(n.p,{children:["Yang lain mengikuti idea-idea Feynman \u2014 dan mereka menghubungkan idea-idea ini dengan teori ",(0,t.jsx)(n.em,{children:"maklumat kuantum"})," yang\nsudah dalam perkembangan.\nBidang ",(0,t.jsx)(n.em,{children:"maklumat dan pengkomputeran kuantum"})," lahir.\nIa telah berkembang menjadi bidang kajian yang kaya dan pelbagai disiplin, dan pelbagai kelebihan kuantum berbanding maklumat dan pengkomputeran klasik telah dikenal pasti dalam pelbagai ",(0,t.jsx)(n.em,{children:"tetapan teori"})," yang melibatkan komunikasi, pengkomputeran, dan kriptografi."]}),"\n",(0,t.jsx)(n.h3,{id:"quantum-computing-in-practice",children:"Pengkomputeran kuantum dalam praktik"}),"\n",(0,t.jsx)(n.p,{children:"Dari segi praktikal, dua perkara diperlukan untuk memindahkan jenis kelebihan teori ini ke kelebihan dunia nyata: peranti itu sendiri dan metodologi untuk membuka kunci potensi mereka."}),"\n",(0,t.jsx)(n.p,{children:"Tidak seperti komputer klasik, tiada siapa yang mempunyai komputer kuantum dalam poket belakang mereka.\nSehingga baru-baru ini, jika anda mahu bereksperimen dengan komputer kuantum, anda terpaksa membina dan menyelenggarakannya sendiri\n(biasanya dalam makmal bawah tanah yang menyedihkan di universiti atau kemudahan penyelidikan), dan anda hanya akan mempunyai beberapa, qubit yang sangat bising paling banyak.\nTidak lagi begitu.\nPada tahun 2016, IBM Quantum\xae meletakkan pemproses kuantum pertama pada awan.\nIa hanya mempunyai 5 qubit dan kadar ralat yang agak tinggi, tetapi kita telah maju jauh sejak itu.\nKita akan meringkaskan keadaan teknologi semasa dalam bahagian di bawah."}),"\n",(0,t.jsx)(n.p,{children:"Selain membina komputer kuantum, kita juga perlu membangunkan metodologi untuk menggunakannya dengan berkesan.\nWalaupun kemajuan teori dalam algoritma kuantum dan protokol mencadangkan potensi yang kuat, cabaran mencari kegunaan praktikal untuk pengkomputeran kuantum masih di hadapan kita.\nKomputer kuantum hari ini masih belum dapat melakukan pengiraan tahan ralat yang diperlukan untuk memindahkan kelebihan teori yang diketahui ke kelebihan praktikal.\nTetapi mereka berada di luar jangkauan simulasi komputer klasik, dan kita mungkin bertujuan untuk memanfaatkan hakikat ini untuk kuasa pengkomputeran."}),"\n",(0,t.jsx)(n.p,{children:"Dengan kemajuan ini kita mendapati diri kita dengan alat baharu untuk pengkomputeran, dan terpulang kepada kita untuk mengetahui apa yang boleh kita lakukan dengannya."}),"\n",(0,t.jsx)(n.h3,{id:"potential-applications",children:"Aplikasi berpotensi"}),"\n",(0,t.jsx)(n.p,{children:"Tidak dijangkakan bahawa pengkomputeran kuantum akan berguna untuk mengkaji bagaimana kereta berprestasi dalam angin.\nTetapi terdapat proses fizikal lain \u2014 seperti yang terlibat dalam reka bentuk bateri atau dalam tindak balas kimia tertentu \u2014 di mana kemampuan komputer kuantum untuk meniru Alam Semesta boleh membawa kepada kelebihan kuantum.\nSecara lebih umum, terdapat banyak masalah yang terlalu sukar atau mahal walaupun untuk superkomputer mutakhir, termasuk masalah yang sangat relevan dengan masyarakat kita.\nPengkomputeran kuantum mungkin tidak menawarkan penyelesaian untuk semua masalah itu, ia mungkin menawarkan penyelesaian untuk sesetengahnya."}),"\n",(0,t.jsx)(n.p,{children:"Tiga kawasan aplikasi berikut mewakili sasaran dalam kawasan pengkomputeran kuantum yang bising, sebelum pelaksanaan pembetulan ralat kuantum dan toleransi ralat."}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"Pengoptimuman"}),"\n",(0,t.jsx)(n.li,{children:"Mensimulasi Alam Semesta"}),"\n",(0,t.jsx)(n.li,{children:"Mencari struktur dalam data (termasuk pembelajaran mesin)"}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"Kita akan membincangkan topik-topik ini dengan lebih terperinci kemudian dalam kursus."}),"\n",(0,t.jsx)(n.h3,{id:"state-of-the-technology",children:"Keadaan teknologi"}),"\n",(0,t.jsx)(n.p,{children:"Membina komputer kuantum adalah cabaran teknologi yang sukar, dan baru sahaja 8 tahun berlalu sejak komputer kuantum kecil tersedia untuk orang awam.\nDalam 8 tahun itu, kita telah membuat kemajuan dalam banyak aspek."}),"\n",(0,t.jsxs)(n.p,{children:["Pelbagai pemproses kuantum IBM kini boleh diakses melalui awan, semuanya mempunyai lebih daripada 100 qubit.\nTetapi bukan sahaja saiz pemproses yang penting \u2014 itu hanyalah satu metrik yang kita ambil berat.\nKualiti Gate juga telah bertambah baik secara dramatik, dan kita juga telah memperkenalkan kaedah mengurangkan dan memitigasi ralat yang wujud dalam sistem kuantum, walaupun semasa kita maju ke arah penciptaan sistem tahan ralat.\nTiga metrik asas \u2014 ",(0,t.jsx)(n.em,{children:"skala"}),", ",(0,t.jsx)(n.em,{children:"kualiti"}),", dan ",(0,t.jsx)(n.em,{children:"kelajuan"})," \u2014 adalah penting untuk menjejaki peningkatan prestasi."]}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Saiz."})," Lebih banyak qubit jelas lebih baik, tetapi hanya jika peningkatan bilangan tidak merendahkan prestasi\n(yang boleh berlaku). Sebenarnya, kita mahukan lebih banyak qubit berkualiti tinggi yang tidak mengganggu satu sama lain\nmelalui crosstalk apabila kita tidak mahu. Cara qubit disambungkan antara satu sama lain juga penting, dan\nmencari cara terbaik untuk melakukan ini merupakan cabaran untuk litar qubit pengalir super."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Kualiti."})," Satu lagi metrik penting yang kita perhatikan, untuk menjejaki peningkatan prestasi dari masa ke masa, adalah ketepercayaan Gate 2-qubit.\nGate yang berjalan pada qubit tunggal tidak terdedah kepada ralat seperti Gate 2-qubit, yang oleh itu menjadi kebimbangan yang lebih besar.\n(Gate 2-qubit juga penting kerana mereka bertanggungjawab untuk mencipta keterjeratan antara qubit, yang\ndihipotesiskan sebagai salah satu fenomena fizik yang memberikan pengkomputeran kuantum kuasanya.)"]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Kelajuan."})," Terakhir adalah kelajuan dan kecekapan. Ringkasnya, masa yang dihabiskan untuk menjalankan program (termasuk bahagian kuantum dan\nklasik) harus sesingkat mungkin."]}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.h2,{id:"conclusion",children:"Kesimpulan"}),"\n",(0,t.jsx)(n.p,{children:"Ini memang masa yang menarik untuk bekerja dalam bidang pengkomputeran kuantum: buat pertama kalinya dalam sejarah kita boleh mula meneroka rantau pengkomputeran yang berada di luar pengkomputeran klasik."}),"\n",(0,t.jsx)(n.p,{children:"T.J. Watson pernah meramalkan dengan terkenal bahawa pasaran dunia hanya untuk beberapa komputer.\nKita mungkin ketawa sekarang betapa jauhnya dia tersalah \u2014 tetapi semasa kita melakukan ini kita mesti mengakui bahawa kita mempunyai kelebihan pandangan ke belakang.\nDan kita juga harus mengakui bahawa, sebagai manusia, kita mempunyai kecenderungan umum untuk sangat meremehkan potensi teknologi masa depan.\nSekarang apabila tiba giliran kita dan kita mengambil peranan sebagai pelopor awal pengkomputeran kuantum, kita harus mengingat ini."}),"\n",(0,t.jsx)(n.p,{children:"Pengkomputeran kuantum sering dibandingkan dengan pengkomputeran klasik, sebagai sesuatu yang berbeza secara ketara daripadanya dan dalam persaingan dengannya.\nTetapi dari perspektif yang lebih luas kita dapat melihat pengkomputeran kuantum sebagai hanyalah satu bab lagi dalam kisah yang panjang.\nAdalah sifat kita sebagai manusia untuk mencari cara baharu untuk mengira dan memanfaatkan kuasa yang dunia semula jadi sediakan kepada kita untuk melakukan ini.\nKita telah melakukan ini selama berabad-abad.\nPengkomputeran kuantum menawarkan kita alat baharu dalam usaha ini dan terpulang kepada kita untuk menemui bagaimana kita boleh memanfaatkan kuasa yang ditawarkannya kepada kita."})]})}function d(a={}){const{wrapper:n}={...(0,u.R)(),...a.components};return n?(0,t.jsx)(n,{...a,children:(0,t.jsx)(s,{...a})}):s(a)}},28453(a,n,e){e.d(n,{R:()=>k,x:()=>m});var i=e(96540);const t={},u=i.createContext(t);function k(a){const n=i.useContext(u);return i.useMemo(function(){return"function"==typeof a?a(n):{...n,...a}},[n,a])}function m(a){let n;return n=a.disableParentContext?"function"==typeof a.components?a.components(t):a.components||t:k(a.components),i.createElement(u.Provider,{value:n},a.children)}}}]);